/// Two-level lookup; `cp` must be below 0x110000.
pub(crate) fn record_index(cp: u32) -> u8 {
    let block = RECORD_INDEX_INDEX.get((cp >> RECORD_INDEX_SHIFT) as usize).copied().unwrap_or(0);
    let offset = (usize::from(block) << RECORD_INDEX_SHIFT) | (cp & ((1 << RECORD_INDEX_SHIFT) - 1)) as usize;
    RECORD_INDEX_BLOCKS.get(offset).copied().unwrap_or(0)
}

